<?php require '../config/database.php';require '../config/auth.php';require_role('admin');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('INSERT INTO questions(question,option_a,option_b,option_c,option_d,correct_answer) VALUES(?,?,?,?,?,?)');$q->execute([$_POST['question'],$_POST['a'],$_POST['b'],$_POST['c'],$_POST['d'],$_POST['correct']]);$msg='Question added.';}$rows=$pdo->query('SELECT * FROM questions ORDER BY id DESC')->fetchAll();$page_title='Question Manager';require '../includes/header.php';?><h1>Question Manager</h1><?php if($msg):?><div class="alert success"><?=$msg?></div><?php endif;?><div class="card"><form method="post"><div class="form"><label>Question</label><input name="question" required></div><?php foreach(['a','b','c','d'] as $x):?><div class="form"><label>Option <?=strtoupper($x)?></label><input name="<?=$x?>" required></div><?php endforeach;?><div class="form"><label>Correct Option</label><select name="correct"><option>A</option><option>B</option><option>C</option><option>D</option></select></div><button class="btn">Add Question</button></form></div><?php require '../includes/footer.php';?>
